const i = $input.first().json || {};
const toText = v => v == null ? '' : (typeof v === 'string' ? v : JSON.stringify(v, null, 2));
let type = String(i.contract_type || '').trim();
if (type === 'عقد إيجار سكني') type = 'عقد إيجار شقة سكنية';
const question = String(i.question || '').trim() || ('ما الأساس القانوني والقواعد المصرية المنطبقة على صياغة ' + (type || 'العقد') + '؟');
const searchQuery = ['القانون المصري', type, String(toText(i.requested_clauses)).slice(0, 120), question.slice(0, 160)].filter(Boolean).join(' ');
return [{ json: {
  contract_type: type,
  jurisdiction: 'Egypt',
  user_role: String(i.user_role || '').trim(),
  question,
  parties: toText(i.parties),
  facts: toText(i.facts),
  requested_clauses: toText(i.requested_clauses),
  contract_requirements: toText(i.contract_requirements),
  job_id: i.job_id ? String(i.job_id) : null,
  search_query: searchQuery
} }];

