// Final node of the internal path: its output is returned synchronously to the calling workflow.
const req = $('Internal Research Request').first().json;
let web = {};
try { web = $('Fallback Web Search').first().json || {}; } catch (e) { web = {}; }
const retrieved = (Array.isArray(web.sources) ? web.sources : []).filter(s => s && typeof s.url === 'string' && s.url.startsWith('http'));
const allowed = new Set(retrieved.map(s => s.url));
const webOk = web.retrieval_status === 'ok' && retrieved.length > 0;
const raw = String($input.first().json.text || '');
let p = {};
let parseError = '';
try {
  const t = raw.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim();
  p = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
} catch (e) { parseError = 'Structured research output could not be parsed as JSON.'; }
const arr = v => Array.isArray(v) ? v : (v ? [v] : []);
const safeUrl = u => (typeof u === 'string' && allowed.has(u)) ? u : null;
const sources = [
  ...retrieved.map(s => ({ title: s.title || '', citation: '', url: s.url, snippet: s.snippet || '', type: 'web', retrieved: true, verification_status: 'unverified - retrieved from web, requires human legal review' })),
  ...arr(p.sources).map(s => { const o = typeof s === 'string' ? { title: s } : (s || {}); const url = safeUrl(o.url); return { title: o.title || '', citation: o.citation || '', url, type: o.type || 'model_knowledge', retrieved: !!url, verification_status: url ? 'unverified - retrieved from web, requires human legal review' : 'unverified - not retrieved, from model knowledge' }; })
];
const citations = arr(p.citations).map(c => { const o = typeof c === 'string' ? { claim: c } : (c || {}); const url = safeUrl(o.url); return { claim: o.claim || '', source_title: o.source_title || '', article_or_ref: o.article_or_ref || '', url, verification_status: url ? 'retrieved' : 'unverified' }; });
const limitations = arr(p.limitations).map(String);
if (!webOk) limitations.push('Web source retrieval failed or returned no results' + (web.error ? (': ' + web.error) : '') + '. All sources are unverified model knowledge.');
if (parseError) limitations.push(parseError);
limitations.push('Research is advisory and must be reviewed by a licensed Egyptian lawyer before use.');
return [{ json: {
  status: parseError ? 'partial' : 'done',
  jurisdiction: 'Egypt',
  contract_type: req.contract_type,
  legal_basis: p.legal_basis || (parseError ? raw : ''),
  applicable_rules: arr(p.applicable_rules),
  sources,
  citations,
  source_urls: retrieved.map(s => s.url),
  uncertainty: p.uncertainty || (webOk ? 'متوسطة' : 'مرتفعة - لم تُسترجع مصادر ويب'),
  limitations,
  missing_facts: arr(p.missing_facts).map(String),
  web_retrieval_status: webOk ? 'ok' : 'failed',
  requires_human_review: true,
  job_id: req.job_id
} }];
